const incoming = $input.first()?.json ?? {};
let input = incoming.input ?? incoming;
if (typeof input === 'string') input = JSON.parse(input);
const executionId = String(input.execution_id ?? '').trim();
if (!/^\d+$/.test(executionId)) throw new Error('execution_id must be numeric');
let includeNodeSummary = input.include_node_summary;
if (includeNodeSummary === undefined || includeNodeSummary === null) includeNodeSummary = true;
if (typeof includeNodeSummary === 'string') {
  if (includeNodeSummary.trim().toLowerCase() === 'true') includeNodeSummary = true;
  else if (includeNodeSummary.trim().toLowerCase() === 'false') includeNodeSummary = false;
}
if (typeof includeNodeSummary !== 'boolean') throw new Error('include_node_summary must be boolean');
return [{ json: { execution_id: executionId, include_node_summary: includeNodeSummary } }];

const response = $input.first()?.json ?? {};
const requested = $('Validate Read Request').first().json;
const statusCode = Number(response.statusCode ?? 200);
const body = response.body ?? response.data ?? response;
if (statusCode >= 400) {
  const message = String(body?.message ?? 'n8n API read failed').replace(/(token|secret|password|authorization|cookie)([\"']?\s*[:=]\s*[\"']?)[^\"',}\s]+/gi, '$1$2[REDACTED]');
  throw new Error('Execution evidence read failed with HTTP ' + statusCode + ': ' + message.slice(0, 200));
}

function redact(value) {
  return String(value ?? '')
    .replace(/(bearer\s+)[^\s\"']+/gi, '$1[REDACTED]')
    .replace(/(token|secret|password|authorization|cookie|signature|api[_-]?key)([\"']?\s*[:=]\s*[\"']?)[^\"',}\s]+/gi, '$1$2[REDACTED]')
    .slice(0, 500);
}

const workflowData = body.workflowData ?? body.data?.workflowData ?? {};
const resultData = body.data?.resultData ?? body.resultData ?? {};
const runData = resultData.runData && typeof resultData.runData === 'object' ? resultData.runData : {};
const nodes = requested.include_node_summary ? Object.entries(runData).map(([nodeName, runs]) => {
  const list = Array.isArray(runs) ? runs : [];
  const last = list[list.length - 1] ?? {};
  const itemCount = Array.isArray(last.data?.main) ? last.data.main.reduce((sum, branch) => sum + (Array.isArray(branch) ? branch.length : 0), 0) : 0;
  return {
    node_name: nodeName,
    status: last.error ? 'error' : 'success',
    start_time: last.startTime ?? null,
    execution_time_ms: last.executionTime ?? null,
    item_count: itemCount,
    error_summary: last.error ? redact(last.error.message ?? last.error.description ?? last.error) : null
  };
}) : [];

const topError = resultData.error ?? body.error ?? null;
return [{ json: {
  ok: true,
  sanitized: true,
  execution_id: String(body.id ?? requested.execution_id),
  workflow_id: String(body.workflowId ?? workflowData.id ?? ''),
  workflow_name: String(workflowData.name ?? body.workflowName ?? ''),
  status: String(body.status ?? (body.finished ? 'success' : topError ? 'error' : 'unknown')),
  mode: String(body.mode ?? ''),
  started_at: body.startedAt ?? null,
  stopped_at: body.stoppedAt ?? null,
  finished: Boolean(body.finished),
  retry_of: body.retryOf ?? null,
  retry_success_id: body.retrySuccessId ?? null,
  node_count: nodes.length,
  nodes,
  error_summary: topError ? redact(topError.message ?? topError.description ?? topError) : null,
  omitted: ['credentials','headers','tokens','signatures','node_payloads','binary_data','customer_content']
} }];
